actions.action:
def created = []
def unchanged = []
def failed = []

def uri = "it/service_desk"
def ticket = "it/service_desk/sd_ticket"
def org = "it/service_desk/sd_organization"
def plan = "it/service_desk/sd_sla_plan"
def tickets = "processIdentifier:\"" + ticket + "\""
def status = { List keys -> tickets + " AND dataSet.tk_status.keyValue:(" + keys.collect { "\"" + it + "\"" }.join(" OR ") + ")" }
// Task zobrazenie: task dokument nema processIdentifier, a processId sa razi
// per verziu siete - transitionId je v tejto appke jedinecny (RUNBOOK 11).
def task = { String transition -> "transitionId:\"" + transition + "\"" }
def customer = ["sd_customer": ticket]
def agent = ["sd_agent": ticket]
def admin = ["sd_admin": ticket]
def staff = ["sd_agent": ticket, "sd_admin": ticket]
def c = { String field -> ticket + "-" + field }
def open = ["new", "in_progress", "waiting", "resolved"]

def views = [
        // ZAKAZNIK
        // "+" zalozi tiket a rovno ho otvori. V zozname su len koncepty -
        // odoslane su v "My Tickets".
        [id: "sd_new_ticket", name: i18n("Create New Ticket", ["sk": "Nový tiket"]),
         type: "Case", icon: "add_comment", query: status(["draft"]),
         nets: [ticket], roles: customer,
         headers: "meta-title," + c("tk_type") + ",meta-creationDate"],
        // Len vlastne: ulohu t_my ma iba autor. Case dopyt na prihlaseneho
        // cloveka sa napisat neda (filter nema <<me>>).
        [id: "sd_my_tickets", name: i18n("My Tickets", ["sk": "Moje tikety"]),
         type: "Task", icon: "inbox", query: task("t_my"),
         nets: [ticket], roles: customer, headers: null],
        // Svoje AJ firemne: viditelnost dava userRef, stlpec "Reported by" ich odlisi.
        [id: "sd_company_tickets", name: i18n("Company Tickets", ["sk": "Tikety organizácie"]),
         type: "Case", icon: "corporate_fare", query: status(open + ["closed", "rejected"]),
         nets: [ticket], roles: customer,
         headers: "meta-title," + c("tk_status") + "," + c("tk_reporter_name") + "," + c("tk_submitted_at") + "," + c("tk_responder")],

        // AGENT a ADMIN
        // Ulohu t_accept vidia len agenti organizacie tiketu (userRef) a admin.
        [id: "sd_triage", name: i18n("Triage", ["sk": "Nové na prevzatie"]),
         type: "Task", icon: "move_to_inbox", query: task("t_accept"),
         nets: [ticket], roles: staff, headers: null],
        [id: "sd_in_progress", name: i18n("Tickets in progress", ["sk": "Tikety v riešení"]),
         type: "Case", icon: "pending_actions", query: status(["in_progress", "waiting"]),
         nets: [ticket], roles: staff,
         headers: "meta-title," + c("tk_status") + "," + c("tk_org_name") + "," + c("tk_priority") + "," + c("sla_resolution_due") + "," + c("tk_responder")],
        [id: "sd_all_tickets", name: i18n("All Tickets", ["sk": "Všetky tikety"]),
         type: "Case", icon: "confirmation_number", query: status(open + ["closed", "rejected"]),
         nets: [ticket], roles: staff,
         headers: "meta-title," + c("tk_status") + "," + c("tk_org_name") + "," + c("tk_priority") + "," + c("sla_response_met") + "," + c("sla_resolution_met")],
        [id: "sd_my_organizations", name: i18n("My Organizations", ["sk": "Moje organizácie"]),
         type: "Case", icon: "domain", query: "processIdentifier:\"" + org + "\"",
         nets: [org], roles: agent,
         headers: "meta-title," + org + "-org_code," + org + "-org_usage"],

        // ADMIN
        [id: "sd_organizations", name: i18n("Organizations", ["sk": "Organizácie"]),
         type: "Case", icon: "domain", query: "processIdentifier:\"" + org + "\"",
         nets: [org], roles: admin,
         headers: "meta-title," + org + "-org_code," + org + "-org_active," + org + "-org_plan," + org + "-org_usage"],
        [id: "sd_sla_plans", name: i18n("SLA Plans", ["sk": "SLA plány"]),
         type: "Case", icon: "timer", query: "processIdentifier:\"" + plan + "\"",
         nets: [plan], roles: admin,
         headers: "meta-title," + plan + "-sp_code," + plan + "-sp_active," + plan + "-sp_max_accounts," + plan + "-sp_max_agents"],
]

// Polozky predoslych verzii Service Desku. Vyhodenie z tejto siete ich
// NEZMAZE - polozky su pripady `preference_filter_item`.
def zastarane = ["sd_tickets", "sd_my_work", "sd_customers", "sd_submissions", "sd_new_request",
                 "sd_podanie", "sd_moje", "sd_na_prevzatie", "sd_v_rieseni", "sd_vsetky", "sd_firmy"]
def zmazane = []
zastarane.each { id ->
    try {
        def stara = menu_item(id)
        if (stara == null) return
        def filter = getFilterFromMenuItem(stara)
        deleteMenuItem(stara)
        if (filter != null) deleteFilter(filter)
        zmazane << id
    } catch (Exception e) {
        failed << (id + " (delete: " + e.getClass().simpleName + ": " + e.message + ")")
    }
}

views.each { v ->
    def id = v.id as String
    try {
        def existing = menu_item(id)
        if (existing != null) {
            def current = getFilterFromMenuItem(existing)
            def currentQuery = ((current?.dataSet?."filter"?.value ?: "") as String)
            def currentNets = ((current?.dataSet?."filter"?.allowedNets ?: []) as List)
                    .collect { it as String } as Set
            def wantNets = (v.nets as List).collect { it as String } as Set
            def currentName = current?.dataSet?."i18n_filter_name"?.value
            def sameName = currentName != null &&
                    (currentName.defaultValue as String) == (v.name.defaultValue as String) &&
                    (currentName.translations ?: [:]) == (v.name.translations ?: [:])
            // Aj ROLY: inak by uz nasadena polozka zostala viditelna vsetkym.
            def currentRoles = [] as Set
            (existing.immediateData ?: []).each { d ->
                if (d.importId == "allowed_roles") {
                    currentRoles = ((d.options ?: [:]).keySet() as Set)
                }
            }
            def wantRoles = (v.roles ?: [:]).collect { r, n -> (r as String) + ":" + (n as String) } as Set
            if (currentQuery == (v.query as String) && currentNets == wantNets && sameName
                    && currentRoles == wantRoles) {
                nastav_zobrazenie(existing, v.nets as List, v.headers)
                pripoj_do_uzla(existing, uri)
                unchanged << id
                return
            }
            deleteMenuItem(existing)
            if (current != null) {
                deleteFilter(current)
            }
        }
        def item = createOrUpdateMenuItem(
                id,                 // menu_item_identifier
                uri,                // URI cesta - musi sedet s uriNodes
                v.type as String,
                v.query as String,
                v.icon as String,
                v.name,             // I18nString
                v.nets as List,     // allowedNets - bez toho ziadne stlpce ani "+"
                v.roles as Map,     // allowed_roles: kto polozku v menu vidi
                [:]                 // bannedRoles - dourcuje aritu na projektovu
        )
        if (item) { created << id } else { failed << id }
        nastav_zobrazenie(item, v.nets as List, v.headers)
    } catch (Exception e) {
        failed << (id + " (" + e.getClass().simpleName + ": " + e.message + ")")
    }
}

// Zosuladenie roli ludi a agentov organizacii - viz komentar v hlavicke.
int roly = 0
try {
    findCases { it.processIdentifier.eq(org) }.each { o ->
        userIdsOf(o.dataSet["org_members"]?.value).each { uid ->
            if (setProcessRole(uid as String, "sd_customer", ticket, "", true)) roly++
        }
        userIdsOf(o.dataSet["org_agents"]?.value).each { uid ->
            if (setProcessRole(uid as String, "sd_agent", ticket, "", true)) roly++
        }
    }
} catch (Exception e) {
    failed << ("roles (" + e.getClass().simpleName + ": " + e.message + ")")
}

// Vysledok do nazvu casu: po createFilterInMenu sa zapis do vlastneho casu
// neuchova, changeCaseProperty prezije.
def summary = "Service Desk menu - " + (created.size() + unchanged.size()) + "/" + views.size() +
        ", roles: " + roly + (zmazane ? (", old removed: " + zmazane.size()) : "")
if (failed) {
    summary = "ERROR Service Desk menu - failed: " + failed.join(", ")
}
changeCaseProperty("title").about { summary }

document.function:
{ def menuItem, def nets, def headers ->
    // `enable_case_title`  - vypnuty dialog "Vyplnte nazov pripadu" pri "+";
    //                        nazov si sklada siet sama.
    // `default_headers`    - predvolene stlpce zoznamu.
    // Ani jedno nie je argument `createOrUpdateMenuItem`.
    if (menuItem == null) return
    def payload = [:]
    if (nets) {
        payload.put("enable_case_title", ["value": false, "type": "boolean"])
        payload.put("case_require_title_in_creation", ["value": false, "type": "boolean"])
    }
    if (headers) {
        payload.put("default_headers", ["value": headers as String, "type": "text"])
    }
    if (payload) {
        setData("view", menuItem, payload)
    }
}

{ def identifier ->
    // `findMenuItem(id)` z ActionDelegate existujucu polozku nenajde (hlada
    // v inom rozsahu), takze by sa pri kazdom spusteni zalozila druha sada.
    def id = ((identifier ?: "") as String).trim()
    if (!id) return null
    def items = findCases { it.processIdentifier.eq("preference_filter_item") }
    return items?.find { ((it.dataSet["menu_item_identifier"]?.value ?: "") as String) == id }
}
